def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Direct string checks for common localhost names
    if host in ("localhost", "127.0.0.1", "::1"):
        return True

    try:
        # Resolve the host to all possible IP addresses
        infos = socket.getaddrinfo(host, None, proto=socket.IPPROTO_TCP)
    except socket.gaierror:
        return False

    # Gather all resolved IPs
    resolved_ips = {info[4][0] for info in infos}

    # Local IPs to compare against
    local_ips = {"127.0.0.1", "::1"}

    # If any resolved IP matches a local IP, consider it local
    return not resolved_ips.isdisjoint(local_ips)

